import{_ as o,o as a,c as t,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Video Export","description":"The architecture behind Local Canvas Stitching vs Cloud FFmpeg.","frontmatter":{"isInternal":true,"type":"Specification","title":"Video Export","description":"The architecture behind Local Canvas Stitching vs Cloud FFmpeg.","tags":["features","specs","architecture"]},"headers":[],"relativePath":"specs/features/video_export.md","filePath":"specs/features/video_export.md"}'),r={name:"specs/features/video_export.md"};function n(s,e,c,d,l,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="video-export-technical-specification" tabindex="-1">Video Export Technical Specification <a class="header-anchor" href="#video-export-technical-specification" aria-label="Permalink to &quot;Video Export Technical Specification&quot;">​</a></h1><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>Sanjeev AI supports two distinct video rendering engines: a zero-cost Local Canvas stitcher for quick previews, and a premium Cloud FFmpeg render for high-quality final exports.</p><h2 id="_2-local-canvas-rendering-zero-cost" tabindex="-1">2. Local Canvas Rendering (Zero-Cost) <a class="header-anchor" href="#_2-local-canvas-rendering-zero-cost" aria-label="Permalink to &quot;2. Local Canvas Rendering (Zero-Cost)&quot;">​</a></h2><ul><li><strong>Mechanism</strong>: Uses HTML5 <code>&lt;canvas&gt;</code> and <code>MediaRecorder</code> API.</li><li><strong>Process</strong>: Iterates through the timeline, drawing the visual for each scene onto a hidden canvas for the duration of the corresponding audio clip.</li><li><strong>Limitations</strong>: Max resolution depends on the browser. Frame rate drops can cause audio de-sync. Cannot easily process advanced crossfades or Ken Burns effects efficiently.</li><li><strong>Use Case</strong>: Quick previews, drafting.</li></ul><h2 id="_3-cloud-ffmpeg-rendering-premium" tabindex="-1">3. Cloud FFmpeg Rendering (Premium) <a class="header-anchor" href="#_3-cloud-ffmpeg-rendering-premium" aria-label="Permalink to &quot;3. Cloud FFmpeg Rendering (Premium)&quot;">​</a></h2><ul><li><strong>Mechanism</strong>: Offloaded to a Google Cloud Run worker or Cloud Function running FFmpeg.</li><li><strong>Process</strong>: The client sends a JSON payload of the timeline (image URLs, audio URLs, durations). The cloud worker downloads the assets, uses FFmpeg to concatenate them, applies transitions, and uploads the final <code>.mp4</code> to Cloud Storage.</li><li><strong>Advantages</strong>: Guaranteed 1080p/4K quality, exact frame-perfect audio sync, ability to render while the user closes the tab.</li><li><strong>Billing</strong>: Deducts credits based on render duration.</li></ul>',7)])])}const g=o(r,[["render",n]]);export{h as __pageData,g as default};
